import { executeScript, showPageToast } from '../utils/execute-script'
import { JS_SNIPPETS } from '../utils/js-snippets'
import { IS_FIREFOX, getActionDataTypes, hasFirefoxDataConsent } from '../utils/firefox-consent'
import { executeFirefoxUserScript, getFirefoxScriptCode } from '../utils/firefox-user-scripts'
import type { KeySetting } from '../utils/url-matching'
import { copyActionParameters } from '../utils/action-parameters'
import type { Browser } from 'wxt/browser'
import { switchToLastUsedTab } from './last-used-tab'
import captureScreenshot from './capture-screenshot'

type ActionHandler = (request: KeySetting) => Promise<boolean> | boolean

/** Actions handled in the content script, not the background action registry. */
const CONTENT_SCRIPT_ACTIONS = ['javascript', 'showcheatsheet', 'toggledarkmode', 'trigger', 'editurl', 'linkhints', 'linkhintsnew']

/** Maximum number of steps allowed in a macro. */
const MAX_MACRO_STEPS = 10

/** Select a tab by direction or index. */
async function selectTab(direction: string): Promise<void> {
  const tabs = await browser.tabs.query({ currentWindow: true })
  if (tabs.length <= 1) return

  const [currentTab] = await browser.tabs.query({ currentWindow: true, active: true })
  const currentIndex = tabs.findIndex((t) => t.id === currentTab.id)
  let target: Browser.tabs.Tab | undefined

  switch (direction) {
    case 'next':
      target = tabs[(currentIndex + 1) % tabs.length]
      break
    case 'previous':
      target = tabs[(currentIndex - 1 + tabs.length) % tabs.length]
      break
    case 'first':
      target = tabs[0]
      break
    case 'last':
      target = tabs[tabs.length - 1]
      break
    default: {
      const index = parseInt(direction) || 0
      if (index >= 1 && index <= tabs.length) {
        target = tabs[index - 1]
      }
    }
  }

  if (target?.id) {
    await browser.tabs.update(target.id, { active: true })
  }
}

/** Check if a URL is safe to navigate to (block data: and vbscript: schemes). */
function isSafeUrl(url: string): boolean {
  const { protocol } = new URL(url)
  return protocol !== 'data:' && protocol !== 'vbscript:'
}

function copyToClipboard(text: string): void {
  executeScript(
    (text: string) => {
      const blob = new Blob([text], { type: 'text/plain' })
      const data = [new ClipboardItem({ 'text/plain': blob })]
      navigator.clipboard.write(data)
    },
    [text],
  )
}

function isSavedTabGroupError(error: unknown): boolean {
  return error instanceof Error && /saved groups are not editable/i.test(error.message)
}

async function getCurrentTabGroupId(): Promise<number | null> {
  const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
  const groupId = (tab as any).groupId ?? -1
  return groupId === -1 ? null : groupId
}

async function updateTabGroupCollapsed(groupId: number, collapsed: boolean): Promise<'success' | 'saved' | 'failed'> {
  try {
    const updatedGroup = await chrome.tabGroups!.update(groupId, { collapsed })
    if (updatedGroup?.collapsed === collapsed) return 'success'
    if (chrome.tabGroups?.get) {
      const group = await chrome.tabGroups.get(groupId)
      if (group.collapsed === collapsed) return 'success'
    }
  } catch (error) {
    if (isSavedTabGroupError(error)) return 'saved'
  }
  return 'failed'
}

function showTabGroupCollapseError(result: 'saved' | 'failed', collapsed: boolean): void {
  if (result === 'saved') {
    showPageToast('Chrome cannot change saved tab groups')
    return
  }
  showPageToast(collapsed ? 'Chrome could not collapse this tab group' : 'Chrome could not expand this tab group')
}

/**
 * Map of action name → handler function.
 * Each handler receives the full request object and returns true if handled.
 */
const actionHandlers: Record<string, ActionHandler> = {
  // -- Downloads --
  cleardownloads: async () => {
    await browser.browsingData.remove({ since: 0 }, { downloads: true })
    return true
  },

  // -- View/Navigation --
  viewsource: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.create({ url: `view-source:${tab.url}` })
    return true
  },
  print: async () => {
    await executeScript(() => window.print())
    return true
  },
  opensettings: async () => {
    const isFirefox = navigator.userAgent.includes('Firefox')
    await browser.tabs.create({ url: isFirefox ? 'about:preferences' : 'chrome://settings', active: true })
    return true
  },
  openextensions: async () => {
    const isFirefox = navigator.userAgent.includes('Firefox')
    await browser.tabs.create({ url: isFirefox ? 'about:addons' : 'chrome://extensions', active: true })
    return true
  },
  openshortcuts: async () => {
    const isFirefox = navigator.userAgent.includes('Firefox')
    await browser.tabs.create({ url: isFirefox ? 'about:addons' : 'chrome://extensions/shortcuts', active: true })
    return true
  },

  // -- Tab switching --
  nexttab: async () => { await selectTab('next'); return true },
  prevtab: async () => { await selectTab('previous'); return true },
  firsttab: async () => { await selectTab('first'); return true },
  lasttab: async () => { await selectTab('last'); return true },

  // -- Tab management --
  newtab: async () => { await browser.tabs.create({}); return true },

  addtoreadinglist: async () => {
    if (IS_FIREFOX || !chrome.readingList?.addEntry) {
      showPageToast('Add to reading list is available in Chrome only')
      return true
    }
    if (!await chrome.permissions.contains({ permissions: ['readingList'] })) {
      const granted = await chrome.permissions.request({ permissions: ['readingList'] })
      if (!granted) {
        showPageToast('Cannot add this page: Reading List permission was denied')
        return true
      }
    }
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (!tab?.url) {
      showPageToast('This tab cannot be added to the reading list')
      return true
    }
    try {
      const existingEntries = await chrome.readingList.query({ url: tab.url })
      if (existingEntries.length > 0) {
        showPageToast('Cannot add this page: it is already in Chrome Reading List')
        return true
      }
      await chrome.readingList.addEntry({
        title: tab.title || tab.url,
        url: tab.url,
        hasBeenRead: false,
      })
      showPageToast('Added to Chrome Reading List')
    } catch (error) {
      console.error('Could not add page to Chrome Reading List:', error)
      showPageToast('Could not add this page to Chrome Reading List')
    }
    return true
  },

  newtabright: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.create({ index: tab.index + 1 })
    return true
  },

  reopentab: async () => {
    const sessions = await browser.sessions.getRecentlyClosed({ maxResults: 1 })
    if (sessions[0]) {
      await browser.sessions.restore(sessions[0].tab?.sessionId || sessions[0].window?.sessionId)
    }
    return true
  },

  closetab: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.remove(tab.id!)
    return true
  },

  clonetab: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.duplicate(tab.id!)
    return true
  },

  movetabtonewwindow: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.windows.create({ url: tab.url, state: 'maximized' })
    await browser.tabs.remove(tab.id!)
    return true
  },

  onlytab: async () => {
    const tabs = await browser.tabs.query({ currentWindow: true, pinned: false, active: false })
    await browser.tabs.remove(tabs.map((t) => t.id!))
    return true
  },

  closelefttabs: async () => {
    const [activeTab] = await browser.tabs.query({ currentWindow: true, active: true })
    const tabs = await browser.tabs.query({ currentWindow: true, pinned: false, active: false })
    const ids = tabs.filter((t) => t.index < activeTab.index).map((t) => t.id!)
    await browser.tabs.remove(ids)
    return true
  },

  closerighttabs: async () => {
    const [activeTab] = await browser.tabs.query({ currentWindow: true, active: true })
    const tabs = await browser.tabs.query({ currentWindow: true, pinned: false, active: false })
    const ids = tabs.filter((t) => t.index > activeTab.index).map((t) => t.id!)
    await browser.tabs.remove(ids)
    return true
  },

  closeduplicatetabs: async () => {
    const tabs = await browser.tabs.query({ currentWindow: true })
    const seen = new Set<string>()
    const toClose: number[] = []
    for (const tab of tabs) {
      if (tab.url && seen.has(tab.url)) {
        toClose.push(tab.id!)
      } else if (tab.url) {
        seen.add(tab.url)
      }
    }
    if (toClose.length > 0) await browser.tabs.remove(toClose)
    showPageToast(toClose.length > 0 ? `✓ Closed ${toClose.length} duplicate tab${toClose.length > 1 ? 's' : ''}` : '✓ No duplicates found')
    return true
  },

  sorttabs: async () => {
    const tabs = await browser.tabs.query({ currentWindow: true })
    const pinned = tabs.filter((t) => t.pinned)
    const unpinned = tabs.filter((t) => !t.pinned)
    unpinned.sort((a, b) => (a.title || '').localeCompare(b.title || ''))
    for (let i = 0; i < unpinned.length; i++) {
      await browser.tabs.move(unpinned[i].id!, { index: pinned.length + i })
    }
    showPageToast(`✓ Sorted ${unpinned.length} tabs`)
    return true
  },

  discardtab: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (tab.id) {
      // Switch to next tab first, then discard (can't discard active tab)
      await selectTab('next')
      await browser.tabs.discard(tab.id)
    }
    return true
  },

  audibletab: async () => {
    const tabs = await browser.tabs.query({ audible: true })
    if (tabs.length > 0) {
      await browser.tabs.update(tabs[0].id!, { active: true })
      await browser.windows.update(tabs[0].windowId!, { focused: true })
    } else {
      showPageToast('No tabs playing audio')
    }
    return true
  },

  grouptab: async (request) => {
    const granted = await chrome.permissions.request({ permissions: ['tabGroups'] })
    if (!granted) { showPageToast('Tab group permission is required for this action'); return true }
    if (!chrome.tabs.group) return true
    const tabs = await browser.tabs.query({ currentWindow: true, highlighted: true })
    const [firstId, ...otherIds] = tabs.flatMap(t => t.id === undefined ? [] : [t.id])
    if (firstId === undefined) return true
    const tabIds: [number, ...number[]] = [firstId, ...otherIds]
    const groupId = await chrome.tabs.group({ tabIds })
    if (request.groupname && chrome.tabGroups?.update) {
      await chrome.tabGroups.update(groupId, { title: request.groupname })
    }
    showPageToast(`✓ ${tabIds.length === 1 ? 'Tab' : tabIds.length + ' tabs'} added to new group`)
    return true
  },

  ungrouptab: async () => {
    const granted = await chrome.permissions.request({ permissions: ['tabGroups'] })
    if (!granted) { showPageToast('Tab group permission is required for this action'); return true }
    if (!chrome.tabs.ungroup) return true
    const tabs = await browser.tabs.query({ currentWindow: true, highlighted: true })
    const [firstId, ...otherIds] = tabs.flatMap(t => t.id === undefined ? [] : [t.id])
    if (firstId === undefined) return true
    const tabIds: [number, ...number[]] = [firstId, ...otherIds]
    await chrome.tabs.ungroup(tabIds)
    showPageToast(`✓ ${tabIds.length === 1 ? 'Tab' : tabIds.length + ' tabs'} removed from group`)
    return true
  },

  togglegrouptab: async (request) => {
    const granted = await chrome.permissions.request({ permissions: ['tabGroups'] })
    if (!granted) { showPageToast('Tab group permission is required for this action'); return true }
    if (!chrome.tabs.group || !chrome.tabs.ungroup) return true
    const tabs = await browser.tabs.query({ currentWindow: true, highlighted: true })
    if (tabs.length === 0) return true
    // If any selected tab is grouped, ungroup all; otherwise group all
    const grouped = tabs.filter((t) => t.groupId !== undefined && t.groupId !== -1)
    const [firstId, ...otherIds] = tabs.flatMap(t => t.id === undefined ? [] : [t.id])
    if (firstId === undefined) return true
    const tabIds: [number, ...number[]] = [firstId, ...otherIds]
    if (grouped.length > 0) {
      await chrome.tabs.ungroup(tabIds)
      showPageToast(`✓ ${tabs.length === 1 ? 'Tab' : tabs.length + ' tabs'} ungrouped`)
    } else {
      const groupId = await chrome.tabs.group({ tabIds })
      if (request.groupname && chrome.tabGroups?.update) {
        await chrome.tabGroups.update(groupId, { title: request.groupname })
      }
      showPageToast(`✓ ${tabs.length === 1 ? 'Tab' : tabs.length + ' tabs'} grouped`)
    }
    return true
  },

  namegroup: async (request) => {
    if (!request.groupname) return true
    const granted = await chrome.permissions.request({ permissions: ['tabGroups'] })
    if (!granted) { showPageToast('Tab group permission is required for this action'); return true }
    if (!chrome.tabGroups?.update) return true
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    const groupId = (tab as any).groupId ?? -1
    if (groupId === -1) {
      showPageToast('Tab is not in a group')
      return true
    }
    await chrome.tabGroups.update(groupId, { title: request.groupname })
    showPageToast(`✓ Group named "${request.groupname}"`)
    return true
  },

  collapsegroup: async () => {
    const granted = await chrome.permissions.request({ permissions: ['tabGroups'] })
    if (!granted) { showPageToast('Tab group permission is required for this action'); return true }
    if (!chrome.tabGroups?.update) return true
    const groupId = await getCurrentTabGroupId()
    if (groupId === null) {
      showPageToast('Tab is not in a group')
      return true
    }
    const result = await updateTabGroupCollapsed(groupId, true)
    if (result === 'success') {
      showPageToast('✓ Group collapsed')
    } else {
      showTabGroupCollapseError(result, true)
    }
    return true
  },

  selecttableft: async () => {
    const tabs = await browser.tabs.query({ currentWindow: true })
    const highlighted = await browser.tabs.query({ currentWindow: true, highlighted: true })
    if (highlighted.length === 0 || tabs.length === 0) return true
    // Find leftmost highlighted tab and extend selection one to the left
    const indices = highlighted.map((t) => t.index).sort((a, b) => a - b)
    const leftmost = indices[0]
    if (leftmost > 0 && chrome.tabs.highlight) {
      const newIndices = [...new Set([leftmost - 1, ...indices])]
      await chrome.tabs.highlight({ tabs: newIndices })
    }
    return true
  },

  selecttabright: async () => {
    const tabs = await browser.tabs.query({ currentWindow: true })
    const highlighted = await browser.tabs.query({ currentWindow: true, highlighted: true })
    if (highlighted.length === 0 || tabs.length === 0) return true
    // Find rightmost highlighted tab and extend selection one to the right
    const indices = highlighted.map((t) => t.index).sort((a, b) => a - b)
    const rightmost = indices[indices.length - 1]
    if (rightmost < tabs.length - 1 && chrome.tabs.highlight) {
      const newIndices = [...new Set([...indices, rightmost + 1])]
      await chrome.tabs.highlight({ tabs: newIndices })
    }
    return true
  },

  togglepin: async () => {
    const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
    await browser.tabs.update(tab.id!, { pinned: !tab.pinned })
    return true
  },

  togglemute: async () => {
    const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
    await browser.tabs.update(tab.id!, { muted: !tab.mutedInfo?.muted })
    return true
  },

  copyurl: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    copyToClipboard(tab.url!.trim())
    showPageToast('✓ URL copied')
    return true
  },

  copypagetitle: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    copyToClipboard(tab.title || '')
    showPageToast('✓ Title copied')
    return true
  },

  copytitleurl: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    copyToClipboard(`${tab.title} - ${tab.url}`)
    showPageToast('✓ Title & URL copied')
    return true
  },

  copytitleurlmarkdown: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    copyToClipboard(`[${tab.title}](${tab.url})`)
    showPageToast('✓ Markdown link copied')
    return true
  },

  openclipboardurl: async () => {
    const granted = await browser.permissions.request({ permissions: ['clipboardRead'] })
    if (!granted) {
      showPageToast('Clipboard permission is required for this action')
      return true
    }
    const results = await executeScript(() => navigator.clipboard.readText())
    const url = results?.[0]?.result?.trim()
    if (url) {
      const fullUrl = url.match(/^https?:\/\//) ? url : `https://${url}`
      await browser.tabs.update(undefined as any, { url: fullUrl })
    }
    return true
  },

  openclipboardurlnewtab: async () => {
    const granted = await browser.permissions.request({ permissions: ['clipboardRead'] })
    if (!granted) {
      showPageToast('Clipboard permission is required for this action')
      return true
    }
    const results = await executeScript(() => navigator.clipboard.readText())
    const url = results?.[0]?.result?.trim()
    if (url) {
      const fullUrl = url.match(/^https?:\/\//) ? url : `https://${url}`
      await browser.tabs.create({ url: fullUrl })
    }
    return true
  },

  openurl: async (request) => {
    if (request.openurl) {
      await browser.tabs.update(undefined as any, { url: request.openurl })
    }
    return true
  },

  searchgoogle: async () => {
    const results = await executeScript(() => window.getSelection()?.toString())
    const selection = results?.[0]?.result
    if (selection) {
      const query = encodeURIComponent(selection)
      const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
      await browser.tabs.create({
        url: `https://www.google.com/search?q=${query}`,
        index: tab.index + 1,
      })
    }
    return true
  },

  // -- Tab movement --
  movetableft: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (tab.index > 0) {
      const allTabs = await browser.tabs.query({ currentWindow: true })
      // After moving left, the new left neighbor is at original index - 2
      const newLeftNeighbor = allTabs.find((t: any) => t.index === tab.index - 2)
      const neighborGroupId = newLeftNeighbor ? ((newLeftNeighbor as any).groupId ?? -1) : -1
      const tabGroupId = (tab as any).groupId ?? -1
      const needsTabGroupsPermission =
        !!chrome.tabs?.group && !!chrome.tabs?.ungroup &&
        ((neighborGroupId !== -1 && neighborGroupId !== tabGroupId) ||
        (tabGroupId !== -1 && neighborGroupId !== tabGroupId && !!newLeftNeighbor))

      let canAdjustGroups = true
      if (needsTabGroupsPermission) {
        canAdjustGroups = await chrome.permissions.request({ permissions: ['tabGroups'] })
      }
      await browser.tabs.move(tab.id!, { index: tab.index - 1 })
      if (needsTabGroupsPermission && !canAdjustGroups) {
        showPageToast('Tab group permission is required to move tabs between groups')
      }
      if (canAdjustGroups && chrome.tabs?.group && chrome.tabs?.ungroup) {
        if (neighborGroupId !== -1 && neighborGroupId !== tabGroupId) {
          await chrome.tabs.group({ tabIds: [tab.id!], groupId: neighborGroupId })
        } else if (tabGroupId !== -1 && neighborGroupId !== tabGroupId && newLeftNeighbor) {
          await chrome.tabs.ungroup(tab.id!)
        }
      }
    }
    return true
  },

  movetabright: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    const allTabs = await browser.tabs.query({ currentWindow: true })
    // After moving right, the new right neighbor is at original index + 2
    const newRightNeighbor = allTabs.find((t: any) => t.index === tab.index + 2)
    const neighborGroupId = newRightNeighbor ? ((newRightNeighbor as any).groupId ?? -1) : -1
    const tabGroupId = (tab as any).groupId ?? -1
    const needsTabGroupsPermission =
      !!chrome.tabs?.group && !!chrome.tabs?.ungroup &&
      ((neighborGroupId !== -1 && neighborGroupId !== tabGroupId) ||
      (tabGroupId !== -1 && neighborGroupId !== tabGroupId && !!newRightNeighbor))

    let canAdjustGroups = true
    if (needsTabGroupsPermission) {
      canAdjustGroups = await chrome.permissions.request({ permissions: ['tabGroups'] })
    }
    await browser.tabs.move(tab.id!, { index: tab.index + 1 })
    if (needsTabGroupsPermission && !canAdjustGroups) {
      showPageToast('Tab group permission is required to move tabs between groups')
    }
    if (canAdjustGroups && chrome.tabs?.group && chrome.tabs?.ungroup) {
      if (neighborGroupId !== -1 && neighborGroupId !== tabGroupId) {
        await chrome.tabs.group({ tabIds: [tab.id!], groupId: neighborGroupId })
      } else if (tabGroupId !== -1 && neighborGroupId !== tabGroupId && newRightNeighbor) {
        await chrome.tabs.ungroup(tab.id!)
      }
    }
    return true
  },

  movetabtofirst: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (tab.index > 0) {
      await browser.tabs.move(tab.id!, { index: 0 })
    }
    return true
  },

  movetabtolast: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.move(tab.id!, { index: -1 })
    return true
  },

  // -- Jump to tab --
  gototab: async (request) => {
    const createNewTab = () => browser.tabs.create({ url: request.openurl })
    if (request.matchurl) {
      const queryOption: Browser.tabs.QueryInfo = { url: request.matchurl }
      if (request.currentWindow) queryOption.currentWindow = true
      const tabs = await browser.tabs.query(queryOption)
      if (tabs.length > 0) {
        await browser.tabs.update(tabs[0].id!, { active: true })
        await browser.windows.update(tabs[0].windowId!, { focused: true })
      } else {
        await createNewTab()
      }
    } else {
      await createNewTab()
    }
    return true
  },

  gototabbytitle: async (request) => {
    if (request.matchtitle) {
      const queryOption: Browser.tabs.QueryInfo = { title: request.matchtitle }
      if (request.currentWindow) queryOption.currentWindow = true
      const tabs = await browser.tabs.query(queryOption)
      if (tabs.length > 0) {
        await browser.tabs.update(tabs[0].id!, { active: true })
        await browser.windows.update(tabs[0].windowId!, { focused: true })
      }
    }
    return true
  },

  gototabbyindex: async (request) => {
    if (request.matchindex) {
      await selectTab(request.matchindex)
    }
    return true
  },

  // -- Windows --
  newwindow: async () => { await browser.windows.create({ state: 'maximized' }); return true },
  newprivatewindow: async () => { await browser.windows.create({ incognito: true, state: 'maximized' }); return true },

  closewindow: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.windows.remove(tab.windowId!)
    return true
  },

  fullscreen: async () => {
    const win = await browser.windows.getCurrent()
    const state = win.state === 'fullscreen' ? 'normal' : 'fullscreen'
    await browser.windows.update(win.id!, { state })
    return true
  },

  // -- Zoom --
  zoomin: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    const zoom = await browser.tabs.getZoom(tab.id!)
    await browser.tabs.setZoom(tab.id!, zoom + 0.1)
    return true
  },

  zoomout: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    const zoom = await browser.tabs.getZoom(tab.id!)
    await browser.tabs.setZoom(tab.id!, zoom - 0.1)
    return true
  },

  zoomreset: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.tabs.setZoom(tab.id!, 0)
    return true
  },

  // -- Downloads --
  showlatestdownload: async () => {
    const downloads = await chrome.downloads.search({ orderBy: ['-startTime'], state: 'complete' })
    if (downloads?.length > 0 && chrome.downloads.show) {
      chrome.downloads.show(downloads[0].id)
    }
    return true
  },

  // -- History --
  back: async () => { await executeScript(() => window.history.back()); return true },
  forward: async () => { await executeScript(() => window.history.forward()); return true },
  reload: async () => { await executeScript(() => window.location.reload()); return true },

  hardreload: async () => {
    await browser.tabs.reload({ bypassCache: true } as any)
    return true
  },
  urlup: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (!tab.url) return true
    try {
      const url = new URL(tab.url)
      // Remove trailing slash, then go up one level
      const path = url.pathname.replace(/\/+$/, '')
      if (path && path !== '') {
        const parentPath = path.substring(0, path.lastIndexOf('/')) || '/'
        url.pathname = parentPath
        url.search = ''
        url.hash = ''
        await browser.tabs.update(tab.id!, { url: url.toString() })
      }
    } catch {
      // Invalid URL, ignore
    }
    return true
  },

  urlroot: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (!tab.url) return true
    try {
      const url = new URL(tab.url)
      await browser.tabs.update(tab.id!, { url: url.origin })
    } catch {
      // Invalid URL, ignore
    }
    return true
  },

  urlinc: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (!tab.url) return true
    const match = tab.url.match(/^(.*?(\D|^))(\d+)(\D*)$/)
    if (!match) { showPageToast('No number found in URL'); return true }
    const [, prefix, , numStr, suffix] = match
    const incremented = String(parseInt(numStr, 10) + 1).padStart(numStr.length, '0')
    await browser.tabs.update(tab.id!, { url: prefix + incremented + suffix })
    return true
  },

  urldec: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    if (!tab.url) return true
    const match = tab.url.match(/^(.*?(\D|^))(\d+)(\D*)$/)
    if (!match) { showPageToast('No number found in URL'); return true }
    const [, prefix, , numStr, suffix] = match
    const decremented = String(Math.max(0, parseInt(numStr, 10) - 1)).padStart(numStr.length, '0')
    await browser.tabs.update(tab.id!, { url: prefix + decremented + suffix })
    return true
  },

  // -- Pagination --
  nextpage: async () => {
    const results = await executeScript(() => {
      const linkNext = document.querySelector<HTMLLinkElement>('link[rel="next"]')
      if (linkNext?.href) { window.location.href = linkNext.href; return true }
      const aNext = document.querySelector<HTMLAnchorElement>('a[rel="next"]')
      if (aNext) { aNext.click(); return true }
      const patterns = /^(next|next\s*page|next\s*›|next\s*»|next\s*→|›|»|→|>>|older\s*(posts|entries)?)$/i
      const candidates = document.querySelectorAll<HTMLElement>('a, button, [role="button"]')
      for (const el of candidates) {
        const text = (el.textContent || '').trim()
        const ariaLabel = el.getAttribute('aria-label') || ''
        const title = el.getAttribute('title') || ''
        if (patterns.test(text) || patterns.test(ariaLabel) || patterns.test(title)) {
          const rect = el.getBoundingClientRect()
          if (rect.width > 0 && rect.height > 0) { el.click(); return true }
        }
      }
      return false
    })
    if (!results?.[0]?.result) { showPageToast('No next page link found') }
    return true
  },

  prevpage: async () => {
    const results = await executeScript(() => {
      const linkPrev = document.querySelector<HTMLLinkElement>('link[rel="prev"]')
      if (linkPrev?.href) { window.location.href = linkPrev.href; return true }
      const aPrev = document.querySelector<HTMLAnchorElement>('a[rel="prev"]')
      if (aPrev) { aPrev.click(); return true }
      const patterns = /^(prev|previous|prev\s*page|previous\s*page|prev\s*‹|prev\s*«|‹|«|←|<<|newer\s*(posts|entries)?)$/i
      const candidates = document.querySelectorAll<HTMLElement>('a, button, [role="button"]')
      for (const el of candidates) {
        const text = (el.textContent || '').trim()
        const ariaLabel = el.getAttribute('aria-label') || ''
        const title = el.getAttribute('title') || ''
        if (patterns.test(text) || patterns.test(ariaLabel) || patterns.test(title)) {
          const rect = el.getBoundingClientRect()
          if (rect.width > 0 && rect.height > 0) { el.click(); return true }
        }
      }
      return false
    })
    if (!results?.[0]?.result) { showPageToast('No previous page link found') }
    return true
  },

  // -- Scrolling --
  // Uses focused scrollable element if available, otherwise window (#300).
  // clientHeight/Width > 0 skips inline elements like links, which Firefox reports as overflowing (#1037).
  top: async (r) => {
    const s = r.smoothScrolling ? 'smooth' : 'auto'
    await executeScript((s: string) => {
      const el = document.activeElement
      const t = el && el !== document.body && el.clientHeight > 0 && el.scrollHeight > el.clientHeight ? el : window
      t.scrollTo({ left: 0, top: 0, behavior: s as ScrollBehavior })
    }, [s])
    return true
  },
  bottom: async (r) => {
    const s = r.smoothScrolling ? 'smooth' : 'auto'
    await executeScript((s: string) => {
      const el = document.activeElement
      if (el && el !== document.body && el.clientHeight > 0 && el.scrollHeight > el.clientHeight) {
        el.scrollTo({ left: 0, top: el.scrollHeight, behavior: s as ScrollBehavior })
      } else {
        window.scrollTo({ left: 0, top: document.body.scrollHeight, behavior: s as ScrollBehavior })
      }
    }, [s])
    return true
  },
  scrollup: async (r) => {
    const s = r.smoothScrolling ? 'smooth' : 'auto'
    await executeScript((s: string) => {
      const el = document.activeElement
      const t = el && el !== document.body && el.clientHeight > 0 && el.scrollHeight > el.clientHeight ? el : window
      t.scrollBy({ left: 0, top: -50, behavior: s as ScrollBehavior })
