  },
  scrolldown: async (r) => {
    const s = r.smoothScrolling ? 'smooth' : 'auto'
    await executeScript((s: string) => {
      const el = document.activeElement
      const t = el && el !== document.body && el.clientHeight > 0 && el.scrollHeight > el.clientHeight ? el : window
