  // -- Bookmarks --
  openbookmark: async (request) => {
    const nodes = await browser.bookmarks.search({ title: request.bookmark! })
    const openNode = nodes.reverse().find((n) => n.url && n.title === request.bookmark)
    if (openNode?.url) {
      if (new URL(openNode.url).protocol === 'javascript:') {
        if (IS_FIREFOX) {
          const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
          if (tab?.id === undefined) throw new Error('No active tab is available for this script.')
          await executeFirefoxUserScript(tab.id, request)
          return true
        }
        // Use try/catch for decodeURIComponent — bare % signs cause URIError (#628)
        const body = openNode.url.slice(openNode.url.indexOf(':') + 1)
        let code: string
        try {
          code = decodeURIComponent(body)
        } catch {
          code = body
        }
        await executeScript(
          (code: string) =>
            document.dispatchEvent(new CustomEvent('shortkeys_js_run', { detail: code })),
          [code],
        )
      } else if (isSafeUrl(openNode.url)) {
        await browser.tabs.update(undefined as any, { url: openNode.url })
      }
    }
    return true
  },

  openbookmarknewtab: async (request) => {
    const nodes = await browser.bookmarks.search({ title: request.bookmark! })
    const openNode = nodes.reverse().find((n) => n.url && n.title === request.bookmark)
    if (openNode?.url && isSafeUrl(openNode.url)) {
      await browser.tabs.create({ url: openNode.url })
    }
    return true
  },

  openbookmarkbackgroundtab: async (request) => {
    const nodes = await browser.bookmarks.search({ title: request.bookmark! })
    const openNode = nodes.reverse().find((n) => n.url && n.title === request.bookmark)
    if (openNode?.url && isSafeUrl(openNode.url)) {
      await browser.tabs.create({ url: openNode.url, active: false })
    }
    return true
  },

  openbookmarkbackgroundtabandclose: async (request) => {
    const nodes = await browser.bookmarks.search({ title: request.bookmark! })
    const openNode = nodes.reverse().find((n) => n.url && n.title === request.bookmark)
    if (openNode?.url && isSafeUrl(openNode.url)) {
      const createdTab = await browser.tabs.create({ url: openNode.url, active: false })
      const closeListener = (tabId: number, changeInfo: Browser.tabs.OnUpdatedInfo) => {
        if (tabId === createdTab.id && changeInfo.status === 'complete') {
          browser.tabs.remove(createdTab.id!)
          browser.tabs.onUpdated.removeListener(closeListener)
        }
      }
      browser.tabs.onUpdated.addListener(closeListener)
    }
    return true
  },

  // -- Apps --
  openapp: async (request) => {
    if (request.openappid) {
      await browser.management.launchApp(request.openappid)
    }
    return true
  },

  // -- Misc --
  togglebookmark: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    const existing = await browser.bookmarks.search({ url: tab.url! })
    if (existing.length > 0) {
      await browser.bookmarks.remove(existing[0].id)
      showPageToast('✓ Bookmark removed')
    } else {
      await browser.bookmarks.create({ title: tab.title, url: tab.url })
      showPageToast('✓ Bookmarked')
    }
    return true
  },

  openincognito: async () => {
    const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
    await browser.windows.create({ url: tab.url, incognito: true, state: 'maximized' })
    return true
  },

  // -- Insert text --
  inserttext: async (request) => {
    if (request.inserttext) {
      await executeScript((text: string) => {
        const el = document.activeElement as HTMLInputElement | HTMLTextAreaElement | null
        if (el && ('value' in el)) {
          const start = el.selectionStart ?? el.value.length
          const end = el.selectionEnd ?? el.value.length
          el.value = el.value.slice(0, start) + text + el.value.slice(end)
          el.selectionStart = el.selectionEnd = start + text.length
          el.dispatchEvent(new Event('input', { bubbles: true }))
        } else if (document.activeElement instanceof HTMLElement && document.activeElement.isContentEditable) {
          document.execCommand('insertText', false, text)
        }
      }, [request.inserttext])
    }
    return true
  },

  // -- Focus input --
  focusinput: async () => {
    const results = await executeScript(() => {
      const selector = 'input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=submit]):not([type=button]):not([type=image]):not([type=file]):not([type=reset]):not([disabled]), textarea:not([disabled]), [contenteditable="true"], [contenteditable=""]'
      const elements = document.querySelectorAll<HTMLElement>(selector)
      for (const el of elements) {
        const rect = el.getBoundingClientRect()
        if (rect.width > 0 && rect.height > 0) {
          el.focus()
          return true
        }
      }
      return false
    })
    if (!results?.[0]?.result) {
      showPageToast('No text input found on page')
    }
    return true
  },

  // -- Disable (no-op) --
  disable: () => true,

  // -- Video controls --
  videoplaypause: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) v.paused ? v.play() : v.pause() })
    return true
  },
  videomute: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) v.muted = !v.muted })
    return true
  },
  videofullscreen: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) document.fullscreenElement ? document.exitFullscreen() : v.requestFullscreen() })
    return true
  },
  videospeedup: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) { v.playbackRate = Math.min(v.playbackRate + 0.25, 16) } })
    showPageToast('✓ Speed up')
    return true
  },
  videospeeddown: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) { v.playbackRate = Math.max(v.playbackRate - 0.25, 0.25) } })
    showPageToast('✓ Speed down')
    return true
  },
  videospeedreset: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) v.playbackRate = 1 })
    showPageToast('✓ Speed reset to 1×')
    return true
  },
  videoskipforward: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) v.currentTime += 10 })
    return true
  },
  videoskipback: async () => {
    await executeScript(() => { const v = document.querySelector('video'); if (v) v.currentTime -= 10 })
    return true
  },

  // -- Search providers --
  searchyoutube: async () => {
    const results = await executeScript(() => window.getSelection()?.toString())
    const selection = results?.[0]?.result
    if (selection) {
      const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
      await browser.tabs.create({ url: `https://www.youtube.com/results?search_query=${encodeURIComponent(selection)}`, index: tab.index + 1 })
    }
    return true
  },
  searchwikipedia: async () => {
    const results = await executeScript(() => window.getSelection()?.toString())
    const selection = results?.[0]?.result
    if (selection) {
      const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
      await browser.tabs.create({ url: `https://en.wikipedia.org/w/index.php?search=${encodeURIComponent(selection)}`, index: tab.index + 1 })
    }
    return true
  },
  searchgithub: async () => {
    const results = await executeScript(() => window.getSelection()?.toString())
    const selection = results?.[0]?.result
    if (selection) {
      const [tab] = await browser.tabs.query({ currentWindow: true, active: true })
      await browser.tabs.create({ url: `https://github.com/search?q=${encodeURIComponent(selection)}&type=repositories`, index: tab.index + 1 })
    }
    return true
  },
}

actionHandlers.lastusedtab = async () => { await switchToLastUsedTab(); return true }
actionHandlers.capturescreenshot = async () => { await captureScreenshot(); return true }
actionHandlers.capturefullsizescreenshot = async () => { await captureScreenshot({ fullsize: true }); return true }
actionHandlers.forcecapturefullsizescreenshot = async () => { await captureScreenshot({ fullsize: true, force: true }); return true }
actionHandlers.buttonnexttab = async request => {
  if (request.button) {
    await executeScript((selector: string) => document.querySelector<HTMLElement>(selector)?.click(), [request.button])
  }
  await selectTab('next')
  return true
}

// -- Macro (chained actions) --
actionHandlers.macro = async (request) => {
  const steps = request.macroSteps
  if (!steps || steps.length === 0) return true

  const capped = steps.slice(0, MAX_MACRO_STEPS)
  for (const [stepIndex, step] of capped.entries()) {
    if (!step.action || step.action === 'macro') continue
    const stepRequest: KeySetting = { key: request.key, action: step.action, ...copyActionParameters(step.action, step) }
    if (step.delay && step.delay > 0) {
      await new Promise((resolve) => setTimeout(resolve, step.delay))
    }

    if (step.action === 'javascript' ||
      (IS_FIREFOX && step.action === 'openbookmark' && await getFirefoxScriptCode(step.action, step))) {
      // Run JS macro step directly via executeScript (step carries its own code)
      const code = IS_FIREFOX ? await getFirefoxScriptCode(step.action, step) : step.code || ''
      if (code) {
        if (IS_FIREFOX) {
          const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
          if (tab?.id === undefined) throw new Error('No active tab is available for this script.')
          await executeFirefoxUserScript(tab.id, request, stepIndex)
        } else {
          await executeScript((c: string) => new Function(c)(), [code])
        }
      }
    } else {
      await handleAction(step.action, stepRequest)
    }
  }
  return true
}


// Register snippet-based actions
for (const snippet of JS_SNIPPETS) {
  actionHandlers['script-' + snippet.id] = async () => {
    await executeScript(snippet.run)
    return true
  }
}

/**
 * Handle an action by looking it up in the action registry.
 * Returns true if the action was handled, false otherwise.
 */
export async function handleAction(action: string, request: KeySetting = {} as KeySetting): Promise<boolean> {
  if (!await hasFirefoxDataConsent(getActionDataTypes(action))) {
    throw new Error('Allow data transmission in Shortkeys settings before running this action.')
  }
  if (IS_FIREFOX && action === 'javascript') {
    const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
    if (tab?.id === undefined) throw new Error('No active tab is available for this script.')
    await executeFirefoxUserScript(tab.id, request)
    return true
  }
  if (CONTENT_SCRIPT_ACTIONS.includes(action)) {
    const [tab] = await browser.tabs.query({ active: true, currentWindow: true })
    if (tab?.id === undefined) throw new Error('No active tab is available for this action.')
    await browser.tabs.sendMessage(tab.id, { ...request, action })
    return true
  }
  const handler = actionHandlers[action]
  if (handler) {
    return handler(request)
  }
  return false
}

export { selectTab, CONTENT_SCRIPT_ACTIONS, MAX_MACRO_STEPS }

