        key: 'a', id: 'parent', action: 'macro', trigger: 'wrong',
        macroSteps: [{ action: 'trigger', trigger: 'ctrl+b' }],
      })
      expect(mockTabsSendMessage).toHaveBeenCalledWith(1, {
